html:not([data-theme="light"]) .con-pill.pilots { color: #93c5fd; }
html:not([data-theme="light"]) .con-pill.flightAttendants { color: #6ee7b7; }
html:not([data-theme="light"]) .con-pill.critical, html:not([data-theme="light"]) .con-pill.late { color: #fb7185; }
html:not([data-theme="light"]) .con-pill.warning, html:not([data-theme="light"]) .con-pill.missing { color: #fcd34d; }
html:not([data-theme="light"]) .con-pill.zero { color: var(--text-tertiary); }

/* KPI detail (KpiDetailPanel + the eight *KpiDetail tables) */
.con-detail { display: flex; flex-direction: column; gap: 8px; padding: 6px 16px 16px; }
.con-detail-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.con-detail-title { margin: 0; font-size: 11px; line-height: 1.25; font-weight: 600; color: var(--text-primary); }
.con-detail-asof { padding: 2px 8px; border: 1px solid color-mix(in srgb, var(--accent-primary) 40%, transparent); border-radius: 6px; font-size: 11px; color: var(--text-secondary); }
.con-detail-bar { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: 8px; }
.con-bank-select { padding: 4px 8px; border: 1px solid var(--border-primary); border-radius: 6px; background: var(--surface-card); font-family: inherit; font-size: 11px; font-weight: 500; color: var(--text-primary); }
.con-scope { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 6px 10px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); font-size: 12px; color: var(--text-primary); }
