/* Operations Control Panel (knowledge-base/features/ops-control-panel.md §5). Design tokens come from tokens.css. */
.ops-app { min-height: 100vh; display: flex; flex-direction: column; }
/* The panel's plain controls in the Radar's outlined style. Each selector is wholly inside :where() so it weighs
   nothing: an attribute or :hover left outside would outrank a screen's own class (it boxed the radar's blips). */
:where(.ops-app :is(button, select, input[type="datetime-local"])) { padding: 6px 12px; border: 1px solid var(--border-secondary); border-radius: 6px; background: transparent; color: var(--text-secondary); font: inherit; font-size: 13px; line-height: 1.25; cursor: pointer; }
:where(.ops-app button:hover:not(:disabled)) { border-color: var(--accent-primary); color: var(--text-primary); }
:where(.ops-app button[aria-pressed="true"]) { background: var(--accent-primary-light); border-color: var(--accent-primary); color: var(--text-primary); }
:where(.ops-app button:disabled) { opacity: 0.45; cursor: default; }
:where(.ops-app select option) { background: var(--bg-secondary); color: var(--text-primary); }
/* Segmented controls: one outer border; square seams (global button radius must not show through). */
.ops-view, .ops-timeline-rule, .ops-lang {
  display: inline-flex; align-items: stretch; border: 1px solid var(--border-secondary); border-radius: 8px; overflow: hidden; background: var(--surface-card);
}
.ops-view > button, .ops-timeline-rule > button, .ops-lang > button {
  margin: 0; border: 0; border-radius: 0; border-right: 1px solid var(--border-secondary); background: transparent; color: var(--text-secondary); min-height: 32px; padding: 6px 12px; line-height: 1.25;
}
.ops-view > button:last-child, .ops-timeline-rule > button:last-child, .ops-lang > button:last-child { border-right: 0; }
.ops-view > button:hover:not(:disabled), .ops-timeline-rule > button:hover:not(:disabled), .ops-lang > button:hover:not(:disabled) {
  border-color: var(--border-secondary); color: var(--text-primary); background: var(--surface-hover);
}
.ops-view > button[aria-pressed="true"], .ops-timeline-rule > button[aria-pressed="true"], .ops-lang > button[aria-pressed="true"] {
  background: var(--accent-primary-light); border-color: var(--border-secondary); color: var(--text-primary); font-weight: 700;
}
.ops-header { display: flex; align-items: center; gap: 24px; padding: 8px 16px; border-bottom: 1px solid var(--border-primary); }
.ops-brand { display: flex; align-items: center; gap: 10px; font-weight: 600; white-space: nowrap; }
.ops-logo { height: 30px; width: auto; display: block; }
.ops-tenant-logo { height: 28px; width: 28px; border-radius: 8px; object-fit: cover; display: block; }
.ops-menu { display: flex; gap: 2px; }
.ops-menu a { padding: 6px 12px; border-radius: 6px; color: inherit; text-decoration: none; }
.ops-menu a[aria-current="page"] { background: var(--accent-primary-light); color: var(--text-primary); box-shadow: inset 0 -2px 0 var(--accent-primary); font-weight: 600; }
.ops-operations { padding: 12px 16px; display: flex; flex-direction: row; gap: 12px; }
.ops-clocks { display: flex; flex-wrap: wrap; gap: 12px; }
.ops-clock { display: inline-flex; align-items: baseline; gap: 10px; padding: 8px 16px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); }
.ops-clock-label { font: 600 12px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--text-tertiary); }
.ops-clock-time { font: 700 22px var(--font-mono); color: var(--text-primary); }
.ops-timeline { display: flex; flex-direction: row; gap: 4px; padding: 10px 14px 18px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); color: var(--text-secondary); }
.ops-timeline-head { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-bottom: 6px; }
.ops-timeline-summary { font: 600 14px var(--font-mono); color: var(--text-primary); margin-right: auto; }
.ops-timeline-chips, .ops-timeline-anchor { display: inline-flex; gap: 6px; align-items: center; }
.ops-timeline-chips > button, .ops-timeline-anchor > button { min-height: 32px; }
.ops-timeline-density { display: block; width: 100%; height: 28px; }
.ops-timeline-bar { fill: var(--border-secondary); }
.ops-timeline-bar.on { fill: var(--accent-primary); }
.ops-timeline-track { position: relative; height: 24px; cursor: pointer; touch-action: none; user-select: none; }
.ops-timeline-rail { position: absolute; left: 0; right: 0; top: 10px; height: 4px; border-radius: 2px; background: var(--bg-tertiary); }
.ops-timeline-band { position: absolute; top: 8px; height: 8px; border-radius: 4px; background: color-mix(in srgb, var(--accent-primary) 55%, transparent); cursor: grab; }
.ops-timeline-band:active { cursor: grabbing; }
.ops-timeline-now { position: absolute; top: 0; width: 2px; height: 24px; margin-left: -1px; background: var(--accent-warning); pointer-events: none; }
.ops-timeline-handle { position: absolute; top: 2px; width: 14px; height: 20px; margin-left: -7px; border: 2px solid var(--surface-card); border-radius: 4px; background: var(--text-primary); cursor: ew-resize; }
.ops-timeline-handle:focus-visible { outline: 2px solid var(--accent-primary); outline-offset: 2px; }
.ops-timeline-ticks { position: relative; height: 14px; }
.ops-timeline-tick { position: absolute; transform: translateX(-50%); font: 10px var(--font-mono); color: var(--text-tertiary); }
.ops-timeline-tick:nth-child(odd) { visibility: hidden; }
@media (min-width: 1200px) { .ops-timeline-tick:nth-child(odd) { visibility: visible; } }
.ops-controls { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; }
.ops-presets button[aria-pressed="true"] { font-weight: 700; }
.ops-show { margin-left: auto; display: inline-flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.ops-show-chip { min-height: 32px; padding: 6px 12px; font: 600 12px var(--font-mono); letter-spacing: 0.02em; border-radius: 8px; }
.ops-show-chip--uncrewed { border-color: #f87171; color: #f87171; }
.ops-show-chip--uncrewed[aria-pressed="true"] { background: color-mix(in srgb, #f87171 22%, transparent); border-color: #f87171; color: #fecaca; }
.ops-show-chip--delayed { border-color: #ffb547; color: #ffb547; }
.ops-show-chip--delayed[aria-pressed="true"] { background: color-mix(in srgb, #ffb547 22%, transparent); border-color: #ffb547; color: #ffd89a; }
.ops-show-chip--cancelled { border-color: #f472b6; color: #f472b6; }
.ops-show-chip--cancelled[aria-pressed="true"] { background: color-mix(in srgb, #f472b6 22%, transparent); border-color: #f472b6; color: #fbcfe8; }
html[data-theme="light"] .ops-show-chip--uncrewed[aria-pressed="true"] { color: #b91c1c; background: color-mix(in srgb, #f87171 14%, transparent); }
html[data-theme="light"] .ops-show-chip--delayed[aria-pressed="true"] { color: #92400e; background: color-mix(in srgb, #ffb547 16%, transparent); }
html[data-theme="light"] .ops-show-chip--cancelled[aria-pressed="true"] { color: #9d174d; background: color-mix(in srgb, #f472b6 14%, transparent); }
.ops-show-clear { min-height: 32px; font-size: 12px; }

.ops-placeholder { padding: 24px 16px; }

/* Map | Table | Both — side by side on wide screens, stacked below 1200px. */
.ops-grid { display: flex; flex-direction: column; gap: 12px; }
.ops-grid--both { display: grid; grid-template-columns: minmax(0, 3fr) minmax(0, 2fr); gap: 12px; align-items: start; }
@media (max-width: 1200px) { .ops-grid--both { grid-template-columns: minmax(0, 1fr); } }
.ops-table { overflow-x: auto; }
.ops-time { white-space: nowrap; }

/* The SVG map, after the dcortex-gen2 ops map: a fixed dark field in both themes, in the Radar's green-black.
   Stroke widths and sizes are set per element in screen pixels; the colours live here. */
.ops-map { position: relative; display: block; border: 1px solid #1e2a40; border-radius: 8px; overflow: hidden; background: #0a0f1a; }
.ops-map-head { display: flex; justify-content: space-between; gap: 12px; padding: 6px 12px; font: 600 11px var(--font-mono); letter-spacing: 0.04em; color: #8494ac; text-transform: uppercase; border-bottom: 1px solid #1e2a40; }
.ops-map-asof { color: #5a6a85; text-transform: none; }
.ops-map-svg { display: block; width: 100%; height: 62vh; min-height: 360px; background: #0a0f1a; cursor: grab; touch-action: none; }
.ops-map-svg:active { cursor: grabbing; }
.ops-map-controls { position: absolute; top: 36px; right: 8px; display: flex; gap: 4px; z-index: 1; }
.ops-map-controls button { border-color: #2a3a58; background: #0a0f1a; color: #8494ac; }
.ops-map-controls button:hover { border-color: #3b82f6; color: #e6edf7; }
.ops-map-credit { position: absolute; right: 8px; bottom: 34px; font: 9px var(--font-mono); letter-spacing: 0.06em; color: #5a6a85; opacity: 0.7; pointer-events: none; }
.ops-graticule { fill: none; stroke: #1e2a40; }
.ops-land { fill: #16233a; stroke: #2a3a58; }
.ops-borders { fill: none; stroke: #2a3a58; opacity: 0.7; }
.ops-station-dot { fill: #5a6a85; opacity: 0.55; }
.ops-path { fill: none; stroke: #8494ac; stroke-linecap: round; opacity: 0.22; cursor: pointer; }
.ops-path--departed, .ops-path--airborne { stroke: #34d399; }
.ops-path--landed { stroke: #5a6a85; }
.ops-path--quiet { opacity: 0.22; }
.ops-path--diverted { stroke: #b99cf0; opacity: 1; }
.ops-path--delayed { stroke: #ffb547; opacity: 1; }
.ops-path--cancelled { stroke: #f472b6; opacity: 0.85; }
.ops-path--short { stroke: #f87171; opacity: 1; }
.ops-route:hover .ops-path { opacity: 1; }
.ops-flight-hit { fill: none; stroke: transparent; pointer-events: stroke; cursor: pointer; }
.ops-halo { fill: none; stroke: #8494ac; opacity: 0.5; }
.ops-origin-mark { fill: #8494ac; }
.ops-airport--base .ops-halo { stroke: #34d399; opacity: 0.8; }
.ops-airport--base .ops-origin-mark { fill: #34d399; }
.ops-dest-mark { fill: #8494ac; }
.ops-event { cursor: pointer; }
.ops-event--delay circle { fill: #ffb547; }
.ops-event--delay text { fill: #ffb547; font-family: var(--font-mono); font-weight: 600; paint-order: stroke; stroke: #0a0f1a; stroke-linejoin: round; }
.ops-event--cancelled path { stroke: #f472b6; stroke-linecap: round; }
.ops-event--recovering circle { fill: #34d399; }
.ops-event--recovering text { fill: #34d399; }
.ops-event--diversion path { fill: #0a0f1a; stroke: #b99cf0; }
.ops-event--alert path { fill: #e8c547; stroke: #0a0f1a; }
.ops-event--alert text { fill: #0a0f1a; font-family: var(--font-mono); font-weight: 700; }
.ops-event--short rect { fill: #f87171; stroke: #0a0f1a; }
.ops-event--short text { fill: #0a0f1a; font-family: var(--font-mono); font-weight: 700; }
.ops-crew-icon { fill: #0a0f1a; }
.ops-legend-crew { width: 12px; height: 12px; margin: 0 4px 0 0; vertical-align: middle; overflow: visible; }
.ops-legend-crew .ops-crew-icon { fill: #f87171; }
.ops-station-tasks rect { fill: #e6edf7; stroke: #0a0f1a; }
.ops-station-tasks text { fill: #0a0f1a; font-family: var(--font-mono); font-weight: 700; }
.ops-position circle { fill: #34d399; stroke: #0a0f1a; cursor: pointer; }
.ops-label { font-family: var(--font-mono); letter-spacing: 0.02em; fill: #8494ac; paint-order: stroke; stroke: #0a0f1a; stroke-linejoin: round; pointer-events: none; }
.ops-label--strong { fill: #e6edf7; font-weight: 600; }
.ops-legend { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; margin: 0; padding: 8px 12px; font-size: 12px; color: #8494ac; border-top: 1px solid #1e2a40; }
.ops-legend-title { font: 700 10px var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: #5a6a85; }
.ops-legend-group { display: flex; flex-wrap: wrap; gap: 12px; margin: 0; padding: 0; list-style: none; }
.ops-legend-group--quiet { opacity: 0.55; }
.ops-legend li::before { content: ""; display: inline-block; width: 14px; height: 3px; margin-right: 6px; vertical-align: middle; background: #8494ac; }
.ops-legend--short::before { background: repeating-linear-gradient(90deg, #f87171 0 2px, transparent 2px 5px) !important; }
.ops-legend--delayed::before { background: #ffb547 !important; }
.ops-legend--cancelled::before { background: repeating-linear-gradient(90deg, #f472b6 0 3px, transparent 3px 5px) !important; }
.ops-legend--diverted::before { background: #b99cf0 !important; }
.ops-legend--alert::before { width: 0 !important; height: 0 !important; background: none !important; border-left: 5px solid transparent; border-right: 5px solid transparent; border-bottom: 9px solid #e8c547; }
.ops-legend--other::before { opacity: 0.5; }
.ops-theme { margin-left: auto; min-width: 36px; padding: 6px 10px; border-radius: 6px; font-size: 16px; line-height: 1; }

/* The flight modal (§5d/§5c-3): a status strip, the two ends as cards, then events and crew. */
.ops-detail { display: flex; flex-direction: column; gap: 18px; color: var(--text-primary); }
.ops-muted { color: var(--text-secondary); }
/* A rotating box's bounds grow by up to √2, and transformed boxes count as scrollable overflow: at the foot of a modal the
 * spinner's corners toggled the scrollbar twice a turn. Clipping the row keeps the round ink and drops the box corners. */
.ops-recheck-pending, .ops-loading-note { overflow: clip; }
.ops-recheck-pending { display: flex; align-items: flex-start; gap: 10px; }
.ops-spinner { flex: none; width: 14px; height: 14px; margin-top: 3px; border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: ops-spin 0.8s linear infinite; }
@keyframes ops-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .ops-spinner { animation-duration: 2.4s; } }
.ops-detail-strip { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.ops-pill { display: inline-flex; align-items: center; padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; letter-spacing: 0.02em; background: var(--bg-tertiary); color: var(--text-secondary); }
.ops-pill--departed, .ops-pill--airborne, .ops-pill--crew-full, .ops-pill--ok { background: color-mix(in srgb, var(--accent-success) 18%, transparent); color: var(--accent-success); }
.ops-pill--landed { background: color-mix(in srgb, var(--text-tertiary) 20%, transparent); color: var(--text-secondary); }
.ops-pill--cancelled, .ops-pill--crew-short { background: color-mix(in srgb, var(--accent-error) 18%, transparent); color: var(--accent-error); }
.ops-pill--diverted { background: rgba(185, 156, 240, 0.2); color: #b99cf0; }
.ops-pill--late { background: color-mix(in srgb, var(--accent-warning) 18%, transparent); color: var(--accent-warning); }
.ops-pill--crew-unknown { background: color-mix(in srgb, var(--text-tertiary) 18%, transparent); color: var(--text-tertiary); }
.ops-chip { padding: 3px 8px; border: 1px solid var(--border-secondary); border-radius: 6px; font: 600 12px var(--font-mono); color: var(--text-secondary); }
.ops-legs { display: grid; grid-template-columns: 1fr auto 1fr; align-items: stretch; gap: 12px; }
.ops-legs-arrow { align-self: center; font-size: 22px; color: var(--text-tertiary); }
.ops-leg-card { display: flex; flex-direction: column; gap: 2px; padding: 14px 16px; border: 1px solid var(--border-primary); border-radius: 10px; background: var(--surface-card); }
.ops-leg-side { font: 600 11px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-tertiary); }
.ops-leg-code { font: 700 30px var(--font-mono); letter-spacing: 0.04em; color: var(--text-primary); }
.ops-leg-city { font-size: 13px; color: var(--text-secondary); }
.ops-leg-code[title], [data-testid="ops-place"][title] { cursor: help; }
.ops-leg-date { font-size: 12px; color: var(--text-tertiary); margin-bottom: 8px; }
.ops-leg-times { display: grid; grid-template-columns: max-content 1fr; gap: 4px 14px; margin: 0; font-size: 13px; }
.ops-leg-times dt { color: var(--text-tertiary); }
.ops-leg-times dd { margin: 0; font-family: var(--font-mono); color: var(--text-primary); }
.ops-progress { display: flex; flex-direction: column; gap: 6px; }
.ops-progress-track { height: 6px; border-radius: 3px; background: var(--bg-tertiary); overflow: hidden; }
.ops-progress-fill { height: 100%; background: var(--accent-success); }
.ops-detail-section { display: flex; flex-direction: column; gap: 10px; padding-top: 14px; border-top: 1px solid var(--border-primary); }
.ops-detail-section-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.ops-detail-section-head h3 { margin: 0; font: 600 11px var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-tertiary); }
.ops-detail-section p { margin: 0; }
.ops-event-chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 0; padding: 0; list-style: none; }
.ops-event-chip { padding: 4px 10px; border-radius: 6px; font-size: 13px; background: var(--bg-tertiary); color: var(--text-primary); border-left: 3px solid var(--text-tertiary); }
.ops-event-chip--delay { border-left-color: var(--accent-warning); }
.ops-event-chip--recovering { border-left-color: var(--accent-success); }
.ops-event-chip--alert { border-left-color: #e8c547; }
.ops-event-chip--diversion { border-left-color: #b99cf0; }
.ops-positions { display: flex; flex-wrap: wrap; gap: 8px; margin: 0; padding: 0; list-style: none; }
.ops-position { display: inline-flex; align-items: baseline; gap: 8px; padding: 6px 12px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); }
.ops-position-code { font: 600 12px var(--font-mono); color: var(--text-tertiary); }
.ops-position-count { font: 700 16px var(--font-mono); color: var(--accent-success); }
.ops-position--short { border-color: color-mix(in srgb, var(--accent-error) 60%, transparent); }
.ops-position--short .ops-position-count { color: var(--accent-error); }
.ops-position-deadhead { font: 600 12px var(--font-mono); color: var(--text-tertiary); }
.ops-crew-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 300px), 1fr)); gap: 6px; margin: 0; padding: 0; list-style: none; }
.ops-crew-row { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; padding: 6px 10px; border-radius: 8px; background: var(--surface-card); min-width: 0; }
.ops-crew-pos { min-width: 30px; padding: 2px 6px; border-radius: 4px; background: var(--bg-tertiary); text-align: center; font: 700 11px var(--font-mono); color: var(--text-secondary); }
.ops-crew-name { flex: 1 1 110px; min-width: 0; font-size: 13px; color: var(--text-primary); overflow-wrap: anywhere; }
.ops-crew-row .ops-pill { flex: none; white-space: nowrap; }
.ops-crew-row--deadhead { opacity: 0.75; }
/* the delay re-check: one crew member per row — position, name, verdict, then the rules it names on their own line */
.ops-crew-list--recheck { grid-template-columns: 1fr; }
.ops-crew-list--recheck .ops-crew-row { flex-wrap: wrap; }
.ops-crew-list--recheck .ops-crew-name { flex: 1 1 auto; min-width: 0; }
.ops-crew-list--recheck .ops-pill { white-space: nowrap; flex: none; }
.ops-crew-list--recheck .ops-recheck-rules { flex: 1 0 100%; padding-left: 40px; font-size: 12px; line-height: 1.4; }
/* every hard rule the engine ran, folded under the crew row */
.ops-crew-list--recheck .ops-recheck-rulelist { flex: 1 0 100%; padding-left: 40px; font-size: 12px; line-height: 1.5; color: var(--text-secondary); }
.ops-recheck-rulelist summary { cursor: pointer; color: var(--text-secondary); }
.ops-recheck-rulelist ul { margin: 4px 0 0; padding: 0; list-style: none; }
.ops-recheck-rule--pass > span { color: var(--accent-success); }
.ops-recheck-rule--breach { color: var(--accent-error); }
.ops-recheck-rule--unjudged > span { color: var(--accent-warning); }
.ops-recheck-rule > .ops-recheck-measure { color: var(--text-secondary); }
.ops-pill--recheck-legal { background: color-mix(in srgb, var(--accent-success) 18%, transparent); color: var(--accent-success); }
.ops-pill--recheck-breach { background: color-mix(in srgb, var(--accent-error) 18%, transparent); color: var(--accent-error); }
.ops-pill--recheck-datacheck, .ops-pill--recheck-unchecked { background: color-mix(in srgb, var(--accent-warning) 18%, transparent); color: var(--accent-warning); }
.ops-crew-tag { margin-left: auto; font-size: 11px; color: var(--text-tertiary); }
.ops-rc-find { flex: none; margin-left: auto; white-space: nowrap; padding: 2px 8px; border: 1px solid var(--border-primary); border-radius: 6px; background: var(--bg-tertiary); font-size: 11px; color: var(--text-primary); cursor: pointer; }
.ops-rc-find[aria-pressed="true"] { border-color: var(--accent-error); }
[data-testid="ops-rc-swap"][aria-pressed="true"] { border-color: var(--accent-primary, var(--border-primary)); }
.ops-rc { flex: none; margin-top: 10px; padding: 12px; border: 1px solid var(--border-primary); border-radius: 10px; background: var(--surface-card); max-width: 100%; box-sizing: border-box; overflow: hidden; }
.ops-rc-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 10px; margin-bottom: 8px; }
.ops-rc-head h4 { margin: 0; font-size: 13px; }
.ops-rc-banner { margin: 0 0 8px; padding: 8px 10px; border-left: 3px solid var(--accent-info, var(--border-primary)); border-radius: 6px; background: var(--bg-tertiary); font-size: 12px; line-height: 1.45; color: var(--text-primary); }
.ops-rc-banner--warn { border-left-color: var(--accent-warning, var(--accent-error)); }
.ops-rc-excluded { margin: 0 0 8px; font-size: 11px; }
.ops-rc-group { margin: 0 0 8px; }
.ops-rc-group-head { cursor: pointer; margin: 0 0 6px; font: 600 12px var(--font-mono); color: var(--text-secondary); }
.ops-rc-group--legal > .ops-rc-group-head { color: var(--accent-success); }
.ops-rc-group--illegal > .ops-rc-group-head { color: var(--accent-error); }
.ops-rc-list { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }
.ops-rc-candidate { padding: 10px 12px; border: 1px solid var(--border-primary); border-left-width: 3px; border-radius: 8px; background: var(--bg-tertiary); min-width: 0; }
.ops-rc-candidate--legal { border-left-color: var(--accent-success); }
.ops-rc-candidate--illegal { border-left-color: var(--accent-error); }
.ops-rc-candidate--not-evaluated { border-left-color: var(--accent-warning, var(--text-tertiary)); }
.ops-rc-candidate-head { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.ops-rc-rank { min-width: 18px; font: 700 12px var(--font-mono); color: var(--text-tertiary); text-align: right; }
.ops-rc-avatar { display: inline-grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; background: var(--surface-card); border: 1px solid var(--border-primary); font: 700 11px var(--font-mono); color: var(--text-secondary); flex: none; }
.ops-rc-who { display: flex; flex-direction: column; min-width: 0; }
.ops-rc-name { font-size: 14px; font-weight: 600; color: var(--text-primary); overflow-wrap: anywhere; }
.ops-rc-meta { font: 11px var(--font-mono); overflow-wrap: anywhere; }
.ops-rc-id { font: 11px var(--font-mono); }
.ops-rc-positioning { font-size: 11px; color: var(--accent-warning, var(--text-secondary)); }
.ops-rc-verdict { font-weight: 600; }
.ops-rc-verdict--legal { color: var(--accent-success); }
.ops-rc-verdict--illegal { color: var(--accent-error); }
.ops-rc-verdict--not-evaluated { color: var(--accent-warning, var(--text-secondary)); }
.ops-rc-verdict--needs-data-check { color: var(--text-secondary); }
.ops-rc-datanotes { margin: 8px 0 0 28px; font-size: 12px; color: var(--text-secondary); }
.ops-rc-datanote--breach { color: var(--accent-warning, var(--accent-error)); font-weight: 600; }
.ops-rc-datanotes-head { margin: 0 0 3px; }
.ops-rc-datanotes ul { display: grid; gap: 2px; margin: 0; padding-left: 16px; overflow-wrap: anywhere; }
.ops-rc-expand { margin-left: auto; font-size: 11px; }
.ops-rc-blockers { display: grid; gap: 3px; margin: 8px 0 0 28px; padding: 0; list-style: none; font-size: 12px; line-height: 1.4; }
.ops-rc-blocker { padding-left: 14px; position: relative; color: var(--accent-error); overflow-wrap: anywhere; }
.ops-rc-blocker::before { content: "✕"; position: absolute; left: 0; font-size: 10px; }
.ops-rc-blocker--missing { color: var(--accent-warning, var(--accent-error)); }
.ops-rc-blocker--missing::before { content: "?"; font-weight: 700; }
.ops-rc-blocker--unchecked { color: var(--accent-warning, var(--accent-error)); }
.ops-rc-blocker--unchecked::before { content: "?"; font-weight: 700; }
.ops-rc-blocker--shared { color: var(--text-tertiary); }
.ops-rc-blocker--shared::before { content: ""; }
.ops-rc-note { margin: 6px 0 0 28px; font-size: 12px; }
.ops-rc-rules { width: 100%; table-layout: fixed; margin-top: 10px; border-collapse: collapse; font-size: 12px; }
.ops-rc-col-rule { width: 60%; }
.ops-rc-col-value { width: 24%; }
.ops-rc-col-margin { width: 16%; }
.ops-rc-rules th { text-align: left; font-weight: 600; color: var(--text-tertiary); }
.ops-rc-rules th, .ops-rc-rules td { padding: 4px 6px; border-top: 1px solid var(--border-primary); vertical-align: top; overflow-wrap: break-word; }
.ops-rc-rules td:nth-child(2), .ops-rc-rules td:nth-child(3) { font-family: var(--font-mono); overflow-wrap: normal; white-space: nowrap; }
.ops-rc-mark { display: inline-block; width: 16px; font-weight: 700; }
.ops-rc-rule--pass { color: var(--text-secondary); }
.ops-rc-rule--pass .ops-rc-mark { color: var(--accent-success); }
.ops-rc-rule--fail { color: var(--text-primary); }
.ops-rc-rule--fail .ops-rc-mark, .ops-rc-rule--fail td:nth-child(3) { color: var(--accent-error); }
@media (max-width: 640px) { .ops-legs { grid-template-columns: 1fr; } .ops-legs-arrow { display: none; } }

/* The rules browser (knowledge-base/decisions/control-tower-v3.md §16): the summary strip, tier chips, one table per
   tier, and the rule's detail as a side panel. */
.ops-rules { padding: 12px 16px; display: flex; flex-direction: column; gap: 12px; }
.ops-rules-summary { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px 18px; padding: 10px 14px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); color: var(--text-secondary); }
.ops-rules-generation { font: 700 18px var(--font-mono); color: var(--text-primary); }
.ops-rules-hash, .ops-rules-code { font: 12px var(--font-mono); color: var(--text-tertiary); }
.ops-rules-controls { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; }
.ops-rules-controls input[type="search"] { min-width: 260px; padding: 6px 10px; border-radius: 6px; border: 1px solid var(--border-secondary); background: var(--bg-secondary); color: inherit; }
.ops-rules-tiers { display: inline-flex; flex-wrap: wrap; gap: 6px; }
.ops-rules-tiers button { border-radius: 999px; padding: 4px 12px; border: 1px solid var(--border-secondary); background: transparent; color: inherit; cursor: pointer; }
.ops-rules-tiers button[aria-pressed="true"] { background: var(--bg-tertiary); font-weight: 700; }
.ops-rules-count { margin-left: 4px; padding: 0 6px; border-radius: 999px; background: var(--bg-secondary); font-size: 11px; }
.ops-rules-group { width: 100%; border-collapse: collapse; }
.ops-rules-group caption { text-align: left; padding: 8px 0 4px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; font-size: 12px; color: var(--text-tertiary); }
.ops-rules-group th, .ops-rules-group td { text-align: left; padding: 6px 8px; border-bottom: 1px solid var(--border-primary); vertical-align: top; }
.ops-rules-group tbody tr { cursor: pointer; }
.ops-rules-group tbody tr:hover, .ops-rules-group tbody tr:focus-visible { background: var(--surface-card); outline: none; }
.ops-rules-note { padding: 24px 16px; }
.ops-rules-alarm { border: 1px solid var(--accent-warning); border-radius: 8px; color: var(--accent-warning); }
.ops-rules-detail { position: fixed; top: 0; right: 0; bottom: 0; box-sizing: border-box; width: min(520px, 100vw); overflow-y: auto; padding: 16px 20px; background: var(--bg-secondary); border-left: 1px solid var(--border-secondary); box-shadow: var(--shadow-lg); z-index: 20; }
.ops-rules-detail header { display: flex; align-items: flex-start; gap: 12px; }
.ops-rules-detail h2 { flex: 1; margin: 0; font-size: 17px; }
.ops-rules-detail h3 { margin: 16px 0 6px; font-size: 12px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--text-tertiary); }
.ops-rules-detail header button { border: 0; background: transparent; color: inherit; font-size: 22px; cursor: pointer; }
.ops-rules-values div { display: grid; grid-template-columns: 180px 1fr; gap: 8px; padding: 3px 0; }
.ops-rules-values dt { color: var(--text-tertiary); font: 12px var(--font-mono); }
.ops-rules-values dd { margin: 0; overflow-wrap: anywhere; }
.ops-rules-source { white-space: pre-wrap; font-size: 13px; color: var(--text-secondary); }
.ops-rules-provenance, .ops-rules-citations { margin: 0; padding-left: 18px; font-size: 13px; }
/* §16.1 — how a rule is checked, its category, what it requires, and its tables as grids. */
.ops-rules-badges { display: inline-flex; flex-wrap: wrap; gap: 4px; }
.ops-rules-badge { padding: 1px 8px; border-radius: 999px; font-size: 11px; white-space: nowrap; border: 1px solid var(--border-secondary); }
.ops-rules-badge-checked { border-color: color-mix(in srgb, var(--accent-success) 55%, transparent); color: var(--accent-success); }
.ops-rules-badge-documented_only { border-color: color-mix(in srgb, var(--accent-warning) 55%, transparent); color: var(--accent-warning); }
.ops-rules-badge-informational { color: var(--text-tertiary); }
.ops-rules-badge-category { color: var(--text-tertiary); background: var(--surface-card); }
.ops-rules-requires { margin: 0; font-size: 15px; font-weight: 600; color: var(--text-primary); }
.ops-rules-fdp { margin-top: 10px; font-variant-numeric: tabular-nums; }
.ops-rules-fdp tbody tr, .ops-rules-detail .ops-rules-group tbody tr { cursor: default; }
.ops-rules-fdp td { text-align: right; }
.ops-rules-detail .ops-rules-group th[scope="row"] { font: 12px var(--font-mono); color: var(--text-secondary); }
.ops-rules-list-toggle { border: 0; background: transparent; color: var(--accent-primary); cursor: pointer; padding: 0; text-decoration: underline; }

/* The Codes tab (control-tower-v3 §5a): one card per code table, each window on a 24-hour bar. */
.ops-rules-tabs { display: flex; gap: 6px; border-bottom: 1px solid var(--border-primary); }
.ops-rules-tabs button { padding: 6px 14px; border: 0; border-bottom: 2px solid transparent; background: transparent; color: inherit; cursor: pointer; }
.ops-rules-tabs button[aria-selected="true"] { border-bottom-color: var(--accent-primary); font-weight: 700; }
.ops-codes-card { display: flex; flex-direction: column; gap: 8px; padding: 12px 14px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); }
.ops-codes-card header { display: flex; align-items: baseline; gap: 12px; }
.ops-codes-card h2 { margin: 0; font-size: 16px; }
.ops-codes-sources { margin: 0; padding-left: 18px; font-size: 13px; color: var(--text-secondary); }
.ops-codes-alias { display: block; font-size: 11px; color: var(--text-tertiary); }
.ops-codes-window { display: inline-flex; align-items: center; gap: 10px; white-space: nowrap; }
.ops-codes-bar { position: relative; display: inline-block; width: 160px; height: 10px; border-radius: 5px; background: var(--bg-tertiary); }
.ops-codes-segment { position: absolute; top: 0; bottom: 0; border-radius: 5px; background: var(--accent-primary); }
.ops-codes-alignment { padding: 8px 12px; border-left: 3px solid var(--accent-warning); background: var(--bg-secondary); font-size: 13px; }
.ops-codes-alignment h3 { margin: 0 0 4px; font-size: 12px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--accent-warning); }
.ops-codes-alignment p { margin: 2px 0; }

/* The Parameters tab (control-tower-v3 §3b): the values in force, a pending change with its impact, and the actions. */
.ops-params { display: flex; flex-direction: column; gap: 10px; }
.ops-params-head { display: flex; flex-wrap: wrap; gap: 14px; align-items: baseline; margin: 0; }
.ops-params-actions { display: flex; flex-wrap: wrap; gap: 8px; margin: 0; }
.ops-params-actions button, .ops-params > button { padding: 6px 14px; border-radius: 6px; border: 1px solid var(--border-secondary); background: var(--surface-card); color: inherit; cursor: pointer; }
.ops-params-actions button:disabled { opacity: 0.5; cursor: default; }
.ops-params input { width: 90px; padding: 4px 8px; border-radius: 4px; border: 1px solid var(--accent-primary); background: var(--bg-secondary); color: inherit; }
.ops-params-pending { padding: 10px 14px; border: 1px solid var(--accent-warning); border-radius: 8px; background: var(--bg-secondary); }
.ops-params-pending header { display: flex; flex-wrap: wrap; gap: 12px; align-items: baseline; }
.ops-params-pending ul { margin: 8px 0; padding-left: 18px; }
.ops-params > button { align-self: flex-start; }
.ops-params .ops-rules-group { width: auto; min-width: 420px; }
.ops-params .ops-rules-group td:first-child { width: 260px; }
.ops-params-bar { position: sticky; top: 0; z-index: 2; align-items: center; padding: 8px 12px; border: 1px solid var(--border-secondary); border-radius: 8px; background: var(--bg-secondary); }
.ops-params-count { color: var(--text-tertiary); margin-right: 4px; }
.ops-params-label { display: block; }
.ops-params-key { display: block; font-size: 11px; opacity: 0.7; }
.ops-params-unit { color: var(--text-tertiary); }
.ops-user { display: flex; align-items: center; gap: 8px; margin-left: 12px; font-size: 13px; }
.ops-user-name { font-weight: 600; }
.ops-user-roles { color: var(--text-tertiary); }
.ops-user button { padding: 3px 10px; border-radius: 6px; border: 1px solid var(--border-secondary); background: var(--surface-card); color: inherit; cursor: pointer; }
.ops-sources { display: flex; flex-direction: column; gap: 12px; }
.ops-sources-banner { margin: 0; padding: 10px 14px; border: 1px solid var(--accent-warning); border-radius: 8px; color: var(--accent-warning); font-weight: 600; }
.ops-sources-quote { margin: 6px 0; padding-left: 10px; border-left: 3px solid var(--border-secondary); font-style: italic; }
.ops-sources-runs h3 { display: flex; align-items: center; gap: 12px; }
.ops-horizon { padding: 8px 18px 28px; display: flex; flex-direction: column; gap: 12px; }
.ops-horizon-board, .ops-horizon-summary, .ops-horizon-next, .ops-horizon-delay { background: var(--surface-card); border: 1px solid var(--border-primary); border-radius: 14px; }
.ops-horizon-board, .ops-horizon-summary { padding: 14px 16px; }
.ops-horizon-head, .ops-horizon-tools, .ops-horizon-legend, .ops-horizon-days, .ops-horizon-next-toggle { display: flex; align-items: center; gap: 10px; }
.ops-horizon-head { justify-content: space-between; }
.ops-horizon-head h1 { margin: 0; font-size: 22px; font-weight: 650; color: var(--text-primary); }
.ops-horizon-live { display: inline-flex; align-items: center; gap: 8px; height: 32px; padding: 0 14px; border-radius: 999px; background: var(--accent-primary); color: var(--text-on-accent); font-size: 13px; font-weight: 750; letter-spacing: 0.04em; text-transform: uppercase; }
.ops-horizon-live::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--text-on-accent); }
.ops-horizon-days { margin-top: 12px; flex-wrap: wrap; gap: 2px; }
.ops-horizon-days button { height: 32px; padding: 0 12px; border: none; border-radius: 8px; background: transparent; color: var(--text-secondary); font-size: 13px; font-weight: 650; }
.ops-horizon-days button[aria-pressed="true"] { background: var(--accent-primary); color: var(--text-on-accent); }
.ops-horizon-cal { display: inline-flex; align-items: center; margin-left: 8px; padding-left: 10px; border-left: 1px solid var(--border-primary); }
.ops-horizon-cal input { width: 36px; height: 28px; padding: 0; border: none; background: transparent; color: transparent; cursor: pointer; }
.ops-horizon-cal input::-webkit-calendar-picker-indicator { cursor: pointer; filter: invert(0.75) sepia(1) saturate(3) hue-rotate(80deg); opacity: 0.9; }
.ops-horizon-tools { margin: 12px 0 8px; flex-wrap: wrap; }
.ops-horizon-tools .ops-horizon-days { margin-top: 0; }
.ops-horizon-greet { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 14px; }
.ops-horizon-greet h2 { margin: 0; font-size: 18px; font-weight: 650; }
.ops-horizon-sub { margin-top: 2px; font-size: 13px; color: var(--text-secondary); }
.ops-horizon-actions { display: flex; align-items: center; gap: 8px; }
.ops-horizon-actions a, .ops-horizon-actions button { height: 32px; padding: 0 12px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--bg-primary); color: var(--text-primary); font-size: 13px; font-weight: 650; text-decoration: none; }
.ops-horizon-badge { margin-left: 6px; }
.ops-horizon-split { display: flex; gap: 12px; align-items: flex-start; }
.ops-horizon-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 12px; }
.ops-horizon-status { width: 180px; flex: none; display: flex; flex-direction: column; gap: 8px; }
.ops-horizon-kpi { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; width: 100%; padding: 8px 10px; border: 1px solid var(--border-primary); border-radius: 10px; background: var(--bg-primary); color: var(--text-primary); text-align: left; cursor: pointer; }
.ops-horizon-kpi-title { font-size: 12px; font-weight: 650; }
.ops-horizon-kpi-value { font-size: 18px; font-weight: 700; }
.ops-horizon-kpi-foot { font-size: 11px; color: var(--text-tertiary); }
.ops-horizon-delay { padding: 0; color: var(--text-primary); }
.ops-horizon-delay-list { max-height: 220px; overflow: auto; padding: 0 14px 10px; }
.ops-horizon-delay-row { display: flex; justify-content: space-between; gap: 12px; width: 100%; padding: 7px 0; border: 0; border-top: 1px solid var(--border-primary); background: none; color: inherit; font: inherit; font-size: 13px; text-align: left; cursor: pointer; }
.ops-horizon-dialog li button { border: 0; padding: 0; background: none; color: inherit; font: inherit; text-align: left; cursor: pointer; }
.ops-horizon-scrim { position: fixed; inset: 0; z-index: 40; background: color-mix(in srgb, var(--bg-primary) 35%, transparent); display: flex; align-items: center; justify-content: center; padding: 24px 16px; }
.ops-horizon-dialog { width: min(420px, calc(100% - 32px)); max-height: 70vh; overflow: auto; padding: 14px 16px; border-radius: 12px; background: var(--surface-card); border: 1px solid var(--border-primary); color: var(--text-primary); }
.ops-horizon-dialog--table { width: min(920px, calc(100% - 32px)); max-height: 84vh; }
.ops-horizon-dialog-head { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.ops-horizon-dialog h2 { margin: 0; font-size: 16px; }
.ops-horizon-dialog h3 { margin: 12px 0 4px; font-size: 14px; }
.ops-horizon-dialog table { width: 100%; border-collapse: collapse; font-size: 13px; font-variant-numeric: tabular-nums; }
.ops-horizon-dialog th, .ops-horizon-dialog td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--border-primary); vertical-align: top; }
.ops-horizon-dialog th { color: var(--text-tertiary); font-weight: 650; font-size: 11px; letter-spacing: 0.04em; text-transform: uppercase; }
.ops-horizon-dialog tbody tr button { border: 0; padding: 0; background: none; color: inherit; font: inherit; text-align: left; cursor: pointer; }
.ops-horizon-scope { margin: 2px 0 8px; color: var(--text-secondary); font-size: 13px; }
.ops-horizon-delta { color: #e8a317; font-weight: 700; }
.ops-horizon-row-miss td:first-child { box-shadow: inset 3px 0 0 #f07178; }
.ops-horizon-row-late td:first-child { box-shadow: inset 3px 0 0 #f0c14a; }
.ops-horizon-row-expired td { color: #f07178; }
.ops-horizon-jump { display: flex; justify-content: space-between; gap: 12px; width: 100%; margin-top: 8px; padding: 8px 0; border: none; border-top: 1px solid var(--border-primary); background: transparent; color: inherit; text-align: left; cursor: pointer; }
.ops-horizon-jump:disabled { opacity: 0.55; cursor: default; }
.ops-horizon-dialog input { width: 100%; margin: 8px 0; }
.ops-horizon-caption { font-size: 13px; font-weight: 650; color: var(--text-primary); background: var(--bg-primary); border-radius: 8px; padding: 4px 10px; }
.ops-horizon-modes { display: inline-flex; margin-left: auto; gap: 2px; padding: 3px; border-radius: 10px; background: var(--bg-primary); }
.ops-horizon-modes button, .ops-horizon-stepper button, .ops-horizon-expand { height: 30px; border: none; border-radius: 8px; background: transparent; color: var(--text-secondary); font-size: 13px; font-weight: 650; }
.ops-horizon-modes button { padding: 0 12px; }
.ops-horizon-modes button[aria-pressed="true"] { background: var(--accent-primary); color: var(--text-on-accent); }
.ops-horizon-stepper { display: inline-flex; align-items: center; gap: 2px; padding: 3px 6px; border-radius: 10px; background: var(--bg-primary); }
.ops-horizon-stepper button { width: 28px; padding: 0; }
.ops-horizon-stepper button:disabled { opacity: 0.35; }
.ops-horizon-stepper span { min-width: 48px; text-align: center; font-size: 13px; color: var(--text-secondary); }
.ops-horizon-expand { padding: 0 12px; background: var(--bg-primary); }
.ops-horizon-wire { display: flex; border-radius: 10px; background: var(--bg-primary); overflow: hidden; }
.ops-horizon-gutter { width: 156px; flex: none; position: relative; }
.ops-horizon-lane-name { position: absolute; left: 12px; right: 8px; font-size: 13px; color: var(--text-secondary); }
.ops-horizon-scroll { flex: 1; min-width: 0; overflow-x: scroll; overflow-y: hidden; scrollbar-width: thin; scrollbar-color: var(--accent-primary) color-mix(in srgb, var(--accent-primary) 28%, transparent); }
.ops-horizon-scroll::-webkit-scrollbar { height: 4px; }
.ops-horizon-scroll::-webkit-scrollbar-track { margin-inline: 12%; background: color-mix(in srgb, var(--accent-primary) 28%, transparent); border-radius: 2px; }
.ops-horizon-scroll::-webkit-scrollbar-thumb { background: var(--accent-primary); border-radius: 2px; }
.ops-horizon-plot { position: relative; }
.ops-horizon-band { position: absolute; bottom: 0; }
.ops-horizon-band.alt { background: color-mix(in srgb, var(--accent-primary) 8%, transparent); }
.ops-horizon-tick { position: absolute; top: 8px; transform: translateX(-50%); font-size: 11px; color: var(--text-tertiary); font-variant-numeric: tabular-nums; white-space: nowrap; }
.ops-horizon-daytick { position: absolute; top: 8px; transform: translateX(-50%); font-size: 11px; color: var(--text-secondary); font-weight: 650; white-space: nowrap; }
.ops-horizon-past { position: absolute; left: 0; bottom: 0; background: rgba(0, 0, 0, 0.18); pointer-events: none; }
.ops-horizon-line { position: absolute; left: 0; right: 0; height: 1px; background: var(--border-primary); }
.ops-horizon-now { position: absolute; top: 0; bottom: 0; width: 2px; margin-left: -1px; background: var(--accent-primary); z-index: 2; pointer-events: none; }
.ops-horizon-nowtag { position: absolute; top: 4px; left: 1px; transform: translateX(-50%); z-index: 4; padding: 1px 7px; border-radius: 999px; background: var(--accent-primary); color: var(--text-on-accent); font-size: 11px; font-weight: 750; white-space: nowrap; }
.ops-horizon-dot { position: absolute; z-index: 3; width: 26px; height: 26px; margin-left: -13px; padding: 0; border: none; border-radius: 50%; font-size: 12px; font-weight: 750; line-height: 26px; text-align: center; color: #1a1208; }
.ops-horizon-plot.expanded .ops-horizon-dot { transform: scale(1.4); }
.ops-horizon-dot.past, .ops-horizon-dot.watch { background: #8d99a8; color: #1c2430; }
.ops-horizon-dot.crit { background: #f07178; color: #2a0c10; }
.ops-horizon-dot.warn { background: #f0c14a; color: #2a2208; }
.ops-horizon-legend { margin-top: 8px; font-size: 12px; color: var(--text-tertiary); }
.ops-horizon-legend i { width: 10px; height: 10px; margin-right: 6px; border-radius: 50%; display: inline-block; }
.ops-horizon-legend i.crit { background: #f07178; }
.ops-horizon-legend i.warn { background: #f0c14a; }
.ops-horizon-pop { position: fixed; z-index: 30; min-width: 220px; max-width: 360px; padding: 8px 10px; border-radius: 10px; background: var(--surface-card); color: var(--text-primary); border: 1px solid var(--border-primary); box-shadow: 0 10px 28px rgba(0, 0, 0, 0.35); font-size: 12px; transform: translate(-50%, calc(-100% - 10px)); }
.ops-horizon-pop .tt-head { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; color: var(--text-tertiary); font-size: 11px; font-weight: 700; }
.ops-horizon-pop .tt-time { padding: 1px 6px; border-radius: 8px; background: var(--surface-hover); color: var(--text-primary); }
.ops-horizon-pop .tt-time.crit { color: #f07178; }
.ops-horizon-pop .tt-time.warn { color: #f0c14a; }
.ops-horizon-pop .tt-row { line-height: 1.55; color: var(--text-secondary); }
.ops-horizon-pop .tt-row b { color: var(--text-primary); font-weight: 650; }
.ops-horizon-pop .tt-more { color: var(--text-tertiary); }
.ops-horizon-summary h2 { margin: 0 0 8px; font-size: 12px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--accent-primary); }
.ops-horizon-summary p { margin: 0; color: var(--text-primary); font-size: 14px; }
.ops-horizon-note { margin-top: 8px; color: var(--text-tertiary); font-size: 12px; }
.ops-horizon-next { padding: 0; color: var(--text-primary); }
.ops-horizon-next-toggle { width: 100%; padding: 10px 14px; border: none; border-radius: 12px; background: transparent; color: inherit; text-align: left; cursor: pointer; }
.ops-horizon-next ul { margin: 0; padding: 0 14px 10px; list-style: none; }
.ops-horizon-next li { display: flex; justify-content: space-between; gap: 12px; padding: 7px 0; border-top: 1px solid var(--border-primary); }
.ops-horizon-up { font-weight: 750; }
.ops-horizon-count { min-width: 22px; height: 22px; padding: 0 6px; border-radius: 999px; background: #e85d6c; color: #fff; font-size: 12px; font-weight: 750; display: inline-flex; align-items: center; justify-content: center; }
.ops-horizon-rank { margin-left: auto; color: var(--text-tertiary); font-size: 12px; }
.ops-horizon-chevron { color: var(--text-tertiary); }

/* A box that is still being read says so: a shimmering placeholder instead of a zero or a blank. */
.ops-skel { display: inline-block; border-radius: 4px; background: linear-gradient(90deg, rgba(148,163,184,.14) 25%, rgba(148,163,184,.3) 50%, rgba(148,163,184,.14) 75%); background-size: 200% 100%; animation: ops-skel-shimmer 1.4s ease-in-out infinite; }
.ops-skel--num { width: 2.2ch; height: 1em; vertical-align: -0.1em; }
.ops-skel--line { display: block; height: 10px; margin: 8px 0; }
.ops-skel--block { display: block; height: 48px; margin: 10px 0; border-radius: 6px; }
.ops-loading-note { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--muted, #94a3b8); }
.ops-loading-note::before { content: ""; width: 10px; height: 10px; border-radius: 50%; border: 2px solid currentColor; border-right-color: transparent; animation: ops-skel-spin .8s linear infinite; }
@keyframes ops-skel-shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
@keyframes ops-skel-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .ops-skel, .ops-loading-note::before { animation: none; } }
